python:
import requests

url = "http://api.example.com/v1/users"

payload = {
    "username": "ada",
    "email": "ada@example.com",
    "status": "active"
}
headers = {
    "accept": "application/json",
    "content-type": "application/json"
}

response = requests.post(url, json=payload, headers=headers)

print(response.text)
